CREATE TYPE "ApplicationStatus" AS ENUM ('SAVED','APPLIED','INTERVIEW','TECHNICAL_INTERVIEW','OFFER','REJECTED','WITHDRAWN');
CREATE TYPE "InterviewType" AS ENUM ('HR','BEHAVIORAL','TECHNICAL','LEADERSHIP');
CREATE TYPE "SubscriptionPlan" AS ENUM ('FREE','PRO','CAREER_PRO');
CREATE TYPE "SubscriptionStatus" AS ENUM ('INACTIVE','TRIALING','ACTIVE','PAST_DUE','CANCELED');
ALTER TABLE "User" ADD COLUMN IF NOT EXISTS "portfolioSlug" TEXT, ADD COLUMN IF NOT EXISTS "portfolioPublic" BOOLEAN NOT NULL DEFAULT false;
CREATE UNIQUE INDEX IF NOT EXISTS "User_portfolioSlug_key" ON "User"("portfolioSlug");
ALTER TABLE "CoverLetter" ADD COLUMN IF NOT EXISTS "jobId" TEXT;
CREATE TABLE "ResumeVersion" ("id" TEXT NOT NULL,"cvId" TEXT NOT NULL,"label" TEXT,"snapshot" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ResumeVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AtsAnalysis" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"cvId" TEXT,"overallScore" INTEGER NOT NULL,"structureScore" INTEGER NOT NULL,"formattingScore" INTEGER NOT NULL,"readabilityScore" INTEGER NOT NULL,"contactScore" INTEGER NOT NULL,"experienceScore" INTEGER NOT NULL,"skillsScore" INTEGER NOT NULL,"keywordScore" INTEGER NOT NULL,"impactScore" INTEGER NOT NULL,"grammarScore" INTEGER NOT NULL,"strengths" JSONB NOT NULL,"issues" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AtsAnalysis_pkey" PRIMARY KEY ("id"));
CREATE TABLE "JobOpportunity" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"title" TEXT NOT NULL,"company" TEXT,"location" TEXT,"seniority" TEXT,"description" TEXT NOT NULL,"responsibilities" JSONB,"requiredSkills" JSONB,"preferredSkills" JSONB,"technologies" JSONB,"education" JSONB,"experience" JSONB,"keywords" JSONB,"sourceUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "JobOpportunity_pkey" PRIMARY KEY ("id"));
CREATE TABLE "JobMatch" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"jobId" TEXT NOT NULL,"cvId" TEXT,"overallScore" INTEGER NOT NULL,"skillScore" INTEGER NOT NULL,"keywordScore" INTEGER NOT NULL,"experienceScore" INTEGER NOT NULL,"educationScore" INTEGER NOT NULL,"matchedSkills" JSONB NOT NULL,"missingSkills" JSONB NOT NULL,"unverifiedSkills" JSONB NOT NULL,"recommendations" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "JobMatch_pkey" PRIMARY KEY ("id"));
CREATE TABLE "JobApplication" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"jobId" TEXT,"cvId" TEXT,"coverLetterId" TEXT,"company" TEXT NOT NULL,"jobTitle" TEXT NOT NULL,"location" TEXT,"salary" TEXT,"jobUrl" TEXT,"source" TEXT,"status" "ApplicationStatus" NOT NULL DEFAULT 'SAVED',"appliedAt" TIMESTAMP(3),"deadline" TIMESTAMP(3),"notes" TEXT,"contactPerson" TEXT,"nextAction" TEXT,"interviewAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "JobApplication_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InterviewSession" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"applicationId" TEXT,"type" "InterviewType" NOT NULL,"title" TEXT NOT NULL,"overallScore" INTEGER,"summary" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "InterviewSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InterviewMessage" ("id" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"role" TEXT NOT NULL,"content" TEXT NOT NULL,"feedback" JSONB,"score" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InterviewMessage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AIUsage" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"feature" TEXT NOT NULL,"model" TEXT,"inputTokens" INTEGER,"outputTokens" INTEGER,"estimatedCost" DECIMAL(12,6),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AIUsage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Subscription" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"plan" "SubscriptionPlan" NOT NULL DEFAULT 'FREE',"status" "SubscriptionStatus" NOT NULL DEFAULT 'INACTIVE',"stripeCustomerId" TEXT,"stripeSubscriptionId" TEXT,"stripePriceId" TEXT,"currentPeriodEnd" TIMESTAMP(3),"cancelAtPeriodEnd" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Subscription_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Subscription_userId_key" ON "Subscription"("userId"); CREATE UNIQUE INDEX "Subscription_stripeSubscriptionId_key" ON "Subscription"("stripeSubscriptionId");
CREATE INDEX "ResumeVersion_cvId_createdAt_idx" ON "ResumeVersion"("cvId","createdAt"); CREATE INDEX "AtsAnalysis_userId_createdAt_idx" ON "AtsAnalysis"("userId","createdAt"); CREATE INDEX "AtsAnalysis_cvId_idx" ON "AtsAnalysis"("cvId"); CREATE INDEX "JobOpportunity_userId_createdAt_idx" ON "JobOpportunity"("userId","createdAt"); CREATE INDEX "JobMatch_userId_createdAt_idx" ON "JobMatch"("userId","createdAt"); CREATE INDEX "JobMatch_jobId_idx" ON "JobMatch"("jobId"); CREATE INDEX "JobApplication_userId_status_idx" ON "JobApplication"("userId","status"); CREATE INDEX "JobApplication_userId_createdAt_idx" ON "JobApplication"("userId","createdAt"); CREATE INDEX "InterviewSession_userId_createdAt_idx" ON "InterviewSession"("userId","createdAt"); CREATE INDEX "InterviewMessage_sessionId_createdAt_idx" ON "InterviewMessage"("sessionId","createdAt"); CREATE INDEX "AIUsage_userId_feature_createdAt_idx" ON "AIUsage"("userId","feature","createdAt");
